const txt = a => (a || []).map(t => t.plain_text).join("");
const now = Date.now();
const rows = [];
for (const it of $('Notion Activity Log').all()) {
  const p = it.json.properties || {};
  if (!p["Agent"]) continue;
  const ts = p["Timestamp"]?.date?.start || it.json.created_time;
  rows.push({ agent: p["Agent"]?.select?.name || "Unknown", status: p["Status"]?.select?.name || "", t: Date.parse(ts) || 0, task: txt(p["Task"]?.title), notes: txt(p["Output Notes"]?.rich_text) });
}
// Deterministic newest-first order (do not rely on the Notion sort alone).
rows.sort((a, b) => b.t - a.t);
const lastShield = rows.find(r => r.agent === "Shield/Ops") || null;
// Ignore our own rows so the monitor cannot mask silence or alert on itself.
const recent = rows.filter(r => r.agent !== "Shield/Ops").sort((a, b) => b.t - a.t).slice(0, 200);
let war = false;
for (const it of $('Notion System Flags').all()) {
  const p = it.json.properties || {};
  let title = "";
  for (const k in p) if (p[k].type === "title") title = txt(p[k].title);
  if (/^war mode$/i.test(title.trim())) war = p["Value"]?.checkbox === true;
}
const findings = [];
let level = 0; // 0 OK, 1 WARN, 2 ALERT
const bump = (l, msg) => { level = Math.max(level, l); findings.push(msg); };
const HOUR = 3600e3, STUCK = 30 * 60e3;
// 1. Errors in the last hour per agent (1-2 WARN, 3+ ALERT)
const errs = {};
for (const r of recent) if (r.status === "Error" && now - r.t <= HOUR) errs[r.agent] = (errs[r.agent] || 0) + 1;
for (const a in errs) bump(errs[a] >= 3 ? 2 : 1, `${a}: ${errs[a]} error(s) in the last hour. Recommend Joshua review; consider pausing ${a}.`);
// 2. Stuck agents: latest row is Working/Thinking for over 30 min (over 2h is ALERT)
const latest = {};
for (const r of recent) if (!latest[r.agent]) latest[r.agent] = r;
for (const a in latest) {
  const r = latest[a], age = now - r.t;
  if ((r.status === "Working" || r.status === "Thinking") && age > STUCK)
    bump(age > 4 * STUCK ? 2 : 1, `${a}: stuck in ${r.status} for ${Math.round(age / 60000)} min ("${r.task}"). Recommend checking or pausing ${a}.`);
}
// 3. Silence: only evaluated Mon-Fri 08:00-18:00 America/New_York. The only scheduled writer is the
// weekday 07:00 Conductor (Fri 07:00 to Mon 07:00 is 72h), so the threshold is 72h and never fires off-hours.
const parts = {};
for (const x of new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", weekday: "short", hour: "numeric", hourCycle: "h23" }).formatToParts(new Date(now))) parts[x.type] = x.value;
const businessHours = ["Mon", "Tue", "Wed", "Thu", "Fri"].includes(parts.weekday) && Number(parts.hour) >= 8 && Number(parts.hour) < 18;
if (businessHours && (recent.length === 0 || now - recent[0].t > 72 * HOUR))
  bump(2, "No Activity Log rows in over 72h during a business day (possible silent failure of the agents or the logging path).");
const status = ["OK", "WARN", "ALERT"][level];
const summary = findings.length ? findings.join(" | ") : "No problems found.";
// Dedupe: log only when status/findings signature differs from the latest Shield/Ops row, or that row is 4h+ old. Never log OK.
const norm = s => String(s || "").replace(/\s*\(War Mode is ON[^)]*\)\s*$/, "").replace(/\d+/g, "#").trim();
const curSig = status + "|" + norm(summary.slice(0, 1900));
const lastSig = lastShield ? (lastShield.status === "Error" ? "ALERT" : "WARN") + "|" + norm(lastShield.notes) : null;
const should_log = level > 0 && (!lastShield || curSig !== lastSig || now - lastShield.t >= 4 * HOUR);
return [{ json: { status, findings, war_mode: war, should_log, rows_checked: recent.length, summary: summary + (war ? " (War Mode is ON; read-only check, nothing changed.)" : ""), checked_at: new Date().toISOString() } }];
